test('mounting mode blocks direct no-hole and undersized beads, permits unknown warnings and glue layout',async({page,isMobile})=>{
 await mount(page);await page.evaluate(()=>(window as any).EditorHarness.mountMounting());await expandEditorTools(page);if(isMobile)await page.getByRole('button',{name:'パーツを探す・選択を調整する'}).click();const picker=page.getByRole('region',{name:'追加するパーツを探す'});await picker.getByText('取り付け方・紐の太さ',{exact:true}).click();await picker.getByLabel('取り付け方',{exact:true}).selectOption('through');await picker.getByLabel('紐の太さ（mm）').fill('1');await expect(picker.getByRole('button',{name:'ビーズ',exact:true})).toBeDisabled();await expect(picker.getByRole('button',{name:'大きいビーズ',exact:true})).toBeDisabled();const unknown=picker.getByRole('button',{name:'穴径未確認のビーズ',exact:true});await expect(unknown).toContainText('通せるか未確認');await unknown.click();await expect(page.getByRole('region',{name:'配置プレビュー'}).getByText(/通せるか未確認/)).toBeVisible();await page.getByRole('button',{name:'配置をキャンセル',exact:true}).click();if(isMobile)await page.getByRole('button',{name:'パーツを探す・選択を調整する'}).click();await picker.getByLabel('取り付け方',{exact:true}).selectOption('glue');await expect(picker.getByRole('button',{name:'ビーズ',exact:true})).toBeEnabled();await picker.getByRole('button',{name:'ビーズ',exact:true}).click();await expect(page.getByRole('region',{name:'配置プレビュー'})).toContainText('台座への接着');await page.getByRole('button',{name:'この位置に配置',exact:true}).click();await page.getByRole('button',{name:'保存',exact:true}).click();await expect.poll(()=>page.evaluate(()=>(window as any).EditorHarness.writes.length)).toBe(1);const saved=await page.evaluate(()=>(window as any).EditorHarness.writes[0].payload);expect(saved.nodes).toHaveLength(1);expect(saved.through_attachments).toEqual([]);expect(saved.point_attachments).toEqual([]);expect(saved.paths).toEqual([]);await mount(page);await expect(page.getByLabel('取り付け方',{exact:true})).toHaveValue('glue');
});

