test('photo-estimated upper holes guide batch placement and re-drag without physical attachments',async({page,isMobile})=>{
 await mount(page);await page.evaluate(()=>(window as any).EditorHarness.mountHoleAnchor());await expandEditorTools(page);await page.getByLabel('自動保存').uncheck();await page.getByLabel('ガイドの形').selectOption('v');await page.getByLabel('ガイドの幅（mm）').fill('100');await page.getByLabel('ガイドの下がり（mm）').fill('50');if(isMobile)await page.getByRole('button',{name:'パーツを探す・選択を調整する'}).click();await page.getByRole('button',{name:'ビーズ',exact:true}).click();await expect(page.getByRole('region',{name:'配置プレビュー'})).toContainText('写真・公式説明による目安');await page.getByLabel('配置する個数').fill('3');await page.getByLabel('間隔の決め方').selectOption('manual');await page.getByLabel('中心間隔（mm）').fill('12');
 const canvas=page.getByLabel('デザインキャンバス');await canvas.scrollIntoViewIfNeeded();let r=await canvas.boundingBox();if(!r)throw Error('missing canvas');await canvas.click({position:{x:125*3*r.width/900,y:(350/3+3.2)*3*r.height/700}});await page.getByRole('button',{name:'保存',exact:true}).click();await expect.poll(()=>page.evaluate(()=>(window as any).EditorHarness.writes.length)).toBe(1);const saved=await page.evaluate(()=>(window as any).EditorHarness.writes[0].payload);
 const anchor=(n:any)=>{const t=n.rotation_deg*Math.PI/180;return{x:n.x_mm+3.2*Math.sin(t),y:n.y_mm-3.2*Math.cos(t)};};for(const n of saved.nodes){const h=anchor(n);expect(h.y).toBeCloseTo(h.x+350/3-125,4);}expect(saved.through_attachments).toEqual([]);
 await canvas.scrollIntoViewIfNeeded();r=await canvas.boundingBox();if(!r)throw Error('missing canvas');const first=saved.nodes[0],point=(x:number,y:number)=>({x:r!.x+x*3*r!.width/900,y:r!.y+y*3*r!.height/700}),start=point(first.x_mm,first.y_mm),end=point(175,350/3+3.2);await page.mouse.move(start.x,start.y);await page.mouse.down();await page.mouse.move(end.x,end.y,{steps:5});await page.mouse.up();await expect(page.getByRole('region',{name:'選択パーツの操作'})).toBeVisible();await page.getByRole('button',{name:'保存',exact:true}).click();await expect.poll(()=>page.evaluate(()=>(window as any).EditorHarness.writes.length)).toBe(2);const updated=await page.evaluate(()=>(window as any).EditorHarness.writes[1].payload),h=anchor(updated.nodes[0]);expect(updated.nodes[0].rotation_deg).toBeCloseTo(315,1);expect(h.y).toBeCloseTo(350/3+175-h.x,3);expect(updated.nodes[1]).toEqual(saved.nodes[1]);expect(updated.through_attachments).toEqual([]);
});
