test.beforeAll(async()=>{await build({configFile:false,logLevel:'silent',resolve:{alias:[{find:/.*lib\/supabase\/client$/,replacement:resolve('tests/fixtures/client.ts')}]},define:{'process.env.NODE_ENV':'"production"','process.env':'{}'},build:{outDir:'test-results/editor-harness',emptyOutDir:false,lib:{entry:'tests/fixtures/editorHarness.tsx',name:'EditorHarness',formats:['iife'],fileName:()=> 'editor.js'}}});bundle=readFileSync('test-results/editor-harness/editor.js','utf8');});
async function mount(page:import('@playwright/test').Page,count=0,through=false,imageEdit=false){await page.goto('/parts/new');await expect(page.getByLabel('取込元の商品URL')).toBeEnabled({timeout:15000});page.on('pageerror',e=>console.error('HARNESS PAGE ERROR',e.message));await page.addScriptTag({content:bundle});await page.evaluate(([n,t,i])=>(window as any).EditorHarness.mount(n,t,i),[count,through,imageEdit]);await expect(page.getByRole('heading',{name:imageEdit?'パーツ画像の再編集':'テストデザイン',exact:true})).toBeVisible();if(!imageEdit)await expandEditorTools(page);}
async function expandEditorTools(page:import('@playwright/test').Page){await expect(page.getByText('保存・詳細操作',{exact:true})).toBeVisible();for(const d of await page.locator('details[data-editor-details]').all())if(!await d.evaluate(e=>(e as HTMLDetailsElement).open)){if(await d.isVisible())await d.locator(':scope > summary').click();else await d.evaluate(e=>(e as HTMLDetailsElement).open=true);}}
