test('simulated two-pointer lifecycle cancels previews and leaves the saved structure unchanged',async({page})=>{
 await mount(page,2);
 const canvas=page.getByLabel('デザインキャンバス');await canvas.scrollIntoViewIfNeeded();
 // The browser automation API cannot inject native two-finger input into WebKit.
 // Only pointer capture is stubbed for these explicitly synthetic PointerEvents.
 await canvas.evaluate(element=>{element.setPointerCapture=()=>{};});
 const r=await canvas.boundingBox();if(!r)throw new Error('missing canvas');
 const x=r.x+r.width/2,y=r.y+r.height/2;
 await canvas.dispatchEvent('pointerdown',{pointerId:1,pointerType:'touch',clientX:x-30,clientY:y,button:0});
 await canvas.dispatchEvent('pointerdown',{pointerId:2,pointerType:'touch',clientX:x+30,clientY:y,button:0});
 await canvas.dispatchEvent('pointermove',{pointerId:1,pointerType:'touch',clientX:x-60,clientY:y+10});
 await canvas.dispatchEvent('pointermove',{pointerId:2,pointerType:'touch',clientX:x+60,clientY:y+10});
 await canvas.dispatchEvent('pointercancel',{pointerId:1,pointerType:'touch'});
 await expect(page.getByLabel('編集倍率')).not.toHaveAttribute('data-zoom','3');
 await expect(page.getByRole('button',{name:'元に戻す',exact:true})).toBeDisabled();
 await expect(page.getByRole('button',{name:'保存',exact:true})).toBeDisabled();
});
